package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Supplier;

import static org.junit.jupiter.api.Assertions.*;

class CommandLine_GetParsedOptionValues_Test {

    // Helper to instantiate CommandLine via its private constructor
    private CommandLine newCommandLineInstance() throws Exception {
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(
                java.util.List.class, java.util.List.class, java.util.function.Consumer.class);
        ctor.setAccessible(true);
        return ctor.newInstance(new LinkedList<String>(), new ArrayList<Option>(), null);
    }

    @Test
    void testGetParsedOptionValues_withNullOptionGroup_returnsDefaultArrayReference() throws Exception {
        CommandLine cmd = newCommandLineInstance();
        String[] defaultVal = new String[] { "a", "b" };

        // call public method
        String[] result = cmd.getParsedOptionValues(null, defaultVal);

        // Expect the returned array to equal the provided default (content and reference)
        assertArrayEquals(defaultVal, result);
        assertSame(defaultVal, result);
    }

    @Test
    void testGetParsedOptionValues_withEmptyOptionGroup_returnsDefault() throws Exception {
        CommandLine cmd = newCommandLineInstance();
        OptionGroup group = new OptionGroup(); // no selection set
        Integer[] defaultVal = new Integer[] { 1, 2, 3 };

        Integer[] result = cmd.getParsedOptionValues(group, defaultVal);

        assertArrayEquals(defaultVal, result);
        assertSame(defaultVal, result);
    }

    @Test
    void testPrivateGetParsedOptionValues_supplierIsInvokedWhenNoSelection() throws Exception {
        CommandLine cmd = newCommandLineInstance();
        OptionGroup group = new OptionGroup(); // no selected option

        AtomicBoolean supplierInvoked = new AtomicBoolean(false);
        Supplier<String[]> supplier = () -> {
            supplierInvoked.set(true);
            return new String[] { "x" };
        };

        // Use reflection to invoke the private overload: getParsedOptionValues(OptionGroup, Supplier<T[]>)
        Method privateMethod = CommandLine.class.getDeclaredMethod("getParsedOptionValues",
                OptionGroup.class, Supplier.class);
        privateMethod.setAccessible(true);

        @SuppressWarnings("unchecked")
        String[] result = (String[]) privateMethod.invoke(cmd, group, supplier);

        assertTrue(supplierInvoked.get(), "Supplier should have been invoked when no option selected");
        assertArrayEquals(new String[] { "x" }, result);
    }

    @Test
    void testGetParsedOptionValues_withNullDefault_returnsNull() throws Exception {
        CommandLine cmd = newCommandLineInstance();
        OptionGroup group = new OptionGroup();

        // Pass null as default array
        String[] result = cmd.getParsedOptionValues(group, (String[]) null);

        // Behavior: when default is null and no selected option, expect null returned
        assertNull(result);
    }
}

